package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathRuntimeException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen0Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_StandardNormal_MeanZero_SDOne() {
        // Test with Standard Normal Distribution (mean=0, sd=1)
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);

        // P(X <= 0) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(0.0), DELTA);

        // P(X <= 1) approx 0.841344746
        Assert.assertEquals(0.8413447460685429, dist.cumulativeProbability(1.0), DELTA);

        // P(X <= -1) approx 0.158655253
        Assert.assertEquals(0.15865525393145705, dist.cumulativeProbability(-1.0), DELTA);

        // Extreme values
        Assert.assertEquals(1.0, dist.cumulativeProbability(10.0), DELTA);
        Assert.assertEquals(0.0, dist.cumulativeProbability(-10.0), DELTA);
    }

    @Test
    public void testCumulativeProbability_CustomMeanAndSD() {
        // Test with mean=5, sd=2
        NormalDistributionImpl dist = new NormalDistributionImpl(5.0, 2.0);

        // P(X <= 5) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(5.0), DELTA);

        // P(X <= 7) is same as P(Z <= (7-5)/2) = P(Z <= 1)
        Assert.assertEquals(0.8413447460685429, dist.cumulativeProbability(7.0), DELTA);
    }

    @Test
    public void testCumulativeProbability_WithSetters() {
        NormalDistributionImpl dist = new NormalDistributionImpl();
        dist.setMean(10.0);
        dist.setStandardDeviation(5.0);

        // P(X <= 10) should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(10.0), DELTA);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidSD_Zero() {
        // SD must be positive. If SD is 0, division by zero occurs in the formula.
        // Depending on implementation, this might throw MathIllegalArgumentException in constructor 
        // or result in NaN/Infinity. Based on Apache Commons Math logic, SD must be > 0.
        new NormalDistributionImpl(0.0, 0.0);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testCumulativeProbability_InvalidSD_Negative() {
        new NormalDistributionImpl(0.0, -1.0);
    }

    @Test
    public void testCumulativeProbability_LargeValues() {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);
        // Testing very large x to ensure it approaches 1.0 without error
        Assert.assertEquals(1.0, dist.cumulativeProbability(Double.MAX_VALUE), DELTA);
        // Testing very small x to ensure it approaches 0.0 without error
        Assert.assertEquals(0.0, dist.cumulativeProbability(-Double.MAX_VALUE), DELTA);
    }
}
